-- ============================================================================
-- payer-rules-aetna-telehealth.sql
--
-- Aetna's telehealth position on all 25 in-scope codes, from Aetna's own
-- Telemedicine and Direct Patient Contact Payment Policy.
--
-- WHY THIS FILE EXISTS
-- Aetna answered 'covered', 'documentation_required' and 'prior_auth_required'
-- for all 25 codes and had NO telehealth_allowed rule for any code — except two
-- hand-typed by a person, on 99349 and 99350, which were withdrawn because a
-- typed payer rule is not citable no matter how well formed it is. Withdrawing
-- them was right and left the attribute genuinely empty. This fills it from the
-- document instead.
--
-- WHAT THE DOCUMENT SAYS
-- It carries a positive list, "List of Eligible CPT/HCPCS for Two-way, Synchronous Telemedicine for Commercial Plans",
-- naming the codes Aetna pays via two-way synchronous audiovisual telemedicine
-- with modifier GT, 95 or FR. 13 of the 25 in-scope codes appear on it:
-- the eight home visits, 99417, 99495/99496 and 99497/99498. The other
-- 12 do not occur anywhere in the document.
--
-- WHY 'varies' AND NOT 'covered'
-- CareSource's telehealth rules use 'covered' because Ohio Medicaid's current
-- telehealth rule lists the code. Aetna's document does list these codes, but
-- it says of itself "Last Review: June, 2021", its revision log ends at
-- 01/01/2022, and it tells providers the current list lives in the Availity
-- provider portal. A five-year-old positive list is real evidence and not a
-- guarantee, so the status says "it depends" and the answer says exactly why.
-- Self-insured commercial plans can also depart from the standard policy.
--
-- WHAT IS DELIBERATELY NOT HERE: frequency_limit
-- The other withdrawn rule claimed a frequency limit on 99350. Nothing in this
-- policy, in Aetna's Office Manual, or in its precertification list states a
-- frequency or visit limit for any of these codes — the Office Manual's only
-- hits for "frequency" are about hearing loss and specialty referrals. So no
-- frequency_limit rule is written here. Filling that cell would mean inventing
-- the number, which is precisely what got the original rule withdrawn. The
-- absence is the honest answer and is left visible.
--
-- RETRIEVAL. www.aetna.com returns 403 to non-browser clients; es.aetna.com
-- serves the identical English asset and is the host the rest of Aetna's
-- documents in this library already cite.
-- ============================================================================

BEGIN;

INSERT INTO source_document (id, payer_id, url, document_type, title, retrieved_at, content_hash, cms_license_token_used, source_metadata, extracted_at)
VALUES
  ('f1000000-000f-4000-8000-00000000a00f'::uuid, 'a0000000-0000-4000-8000-000000000301'::uuid, 'https://es.aetna.com/content/dam/aetna/pdfs/aetnacom/pdf/telemedicine.pdf', 'medical_policy',
   'Aetna — Telemedicine and Direct Patient Contact Payment Policy (last review June 2021; revision log through 01/01/2022)',
   now(), 'sha256:a9b8a5e1f09c9550f90d2727c02e22e47960de2e30ee45ed2b08277251922d82', FALSE,
   '{"retrievedVia":"www.aetna.com returns 403 to non-browser clients; es.aetna.com serves the identical English asset"}'::jsonb, now())
ON CONFLICT (id) DO UPDATE SET
  url = EXCLUDED.url, title = EXCLUDED.title, content_hash = EXCLUDED.content_hash,
  document_type = EXCLUDED.document_type, source_metadata = EXCLUDED.source_metadata;

UPDATE payer_rule pr
   SET expiration_date = GREATEST(pr.effective_date, DATE '2022-01-01')
 WHERE pr.expiration_date IS NULL
   AND pr.created_by <> 'extract:aetna-telemedicine-2026-08'
   AND pr.payer_id = 'a0000000-0000-4000-8000-000000000301'::uuid
   AND pr.attribute = 'telehealth_allowed';

INSERT INTO payer_rule (id, payer_id, state, product_line, code, attribute, value, coverage_status, confidence, effective_date, expiration_date, source_doc_id, source_quote, created_by)
VALUES
  ('dcbbb518-adf8-40b8-8dec-74623a85ef05'::uuid, 'a0000000-0000-4000-8000-000000000301'::uuid, 'OH', 'commercial', '99341', 'telehealth_allowed', '{"answer":"Aetna''s Telemedicine and Direct Patient Contact Payment Policy lists 99341 (home visit, new patient) as eligible for two-way, synchronous (real-time) audiovisual telemedicine, under the row \"Home visit for the evaluation and management of a new or established patient\". Bill it with modifier GT, 95 or FR; the policy states Aetna does not pay for asynchronous telemedicine (modifier GQ), which it treats as incidental to the overall episode of care. Treat this as a starting point rather than a guarantee: the policy carries \"Last Review: June, 2021\" and its revision log ends at 01/01/2022, and Aetna directs providers to the Availity provider portal for the current eligible-code list. Self-insured plans can differ from the standard commercial policy. Confirm for the member''s specific plan before billing telehealth.","source":"Aetna — Telemedicine and Direct Patient Contact Payment Policy, retrieved 2026-08-12"}'::jsonb, 'varies', 0.7, DATE '2022-01-01', NULL, 'f1000000-000f-4000-8000-00000000a00f'::uuid, 'Telemedicine and Direct Patient Contact Payment Policy, List of Eligible CPT/HCPCS for Two-way, Synchronous Telemedicine for Commercial Plans — Home visit for the evaluation and management of a new or established patient | 99341, 99342, 99343; 99344, 99345, 99347, 99348, 99349, 99350', 'extract:aetna-telemedicine-2026-08'),
