  ('709a0f76-711f-4f50-8182-29b2b632b18e'::uuid, 'a0000000-0000-4000-8000-000000000301'::uuid, 'OH', 'commercial', '99417', 'telehealth_allowed', '{"answer":"Aetna''s Telemedicine and Direct Patient Contact Payment Policy lists 99417 (prolonged outpatient E/M, each additional 15 minutes) as eligible for two-way, synchronous (real-time) audiovisual telemedicine, under the row \"Prolonged service, inpatient or office\". Bill it with modifier GT, 95 or FR; the policy states Aetna does not pay for asynchronous telemedicine (modifier GQ), which it treats as incidental to the overall episode of care. Treat this as a starting point rather than a guarantee: the policy carries \"Last Review: June, 2021\" and its revision log ends at 01/01/2022, and Aetna directs providers to the Availity provider portal for the current eligible-code list. Self-insured plans can differ from the standard commercial policy. Confirm for the member''s specific plan before billing telehealth.","source":"Aetna — Telemedicine and Direct Patient Contact Payment Policy, retrieved 2026-08-12"}'::jsonb, 'varies', 0.7, DATE '2022-01-01', NULL, 'f1000000-000f-4000-8000-00000000a00f'::uuid, 'Telemedicine and Direct Patient Contact Payment Policy, List of Eligible CPT/HCPCS for Two-way, Synchronous Telemedicine for Commercial Plans — Prolonged service, inpatient or office | 99354, 99355, 99356, 99357', 'extract:aetna-telemedicine-2026-08'),
  ('98e77153-214c-4bc0-8c29-8716a9a97d6d'::uuid, 'a0000000-0000-4000-8000-000000000301'::uuid, 'OH', 'commercial', '99424', 'telehealth_allowed', '{"answer":"Aetna publishes no telemedicine eligibility for 99424 (principal care management, first 30 minutes by a physician). Its Telemedicine and Direct Patient Contact Payment Policy carries a positive list — \"List of Eligible CPT/HCPCS for Two-way, Synchronous Telemedicine for Commercial Plans\" — and 99424 does not appear anywhere in that document. Absence from the list is not a documented denial, so this is recorded as unestablished rather than as not allowed, and it is a weaker signal than it looks: the policy carries \"Last Review: June, 2021\" and its revision log ends at 01/01/2022, while Aetna directs providers to the Availity provider portal for the current eligible-code list. Ask Aetna for the current list before billing this code via telehealth.","source":"Aetna — Telemedicine and Direct Patient Contact Payment Policy, retrieved 2026-08-12"}'::jsonb, 'unknown', 0.6, DATE '2022-01-01', NULL, 'f1000000-000f-4000-8000-00000000a00f'::uuid, 'Telemedicine and Direct Patient Contact Payment Policy — List of Eligible CPT/HCPCS for Two-way, Synchronous Telemedicine for Commercial Plans', 'extract:aetna-telemedicine-2026-08'),
  ('81f18ff0-135c-4811-8427-e57e1f678014'::uuid, 'a0000000-0000-4000-8000-000000000301'::uuid, 'OH', 'commercial', '99425', 'telehealth_allowed', '{"answer":"Aetna publishes no telemedicine eligibility for 99425 (principal care management, each additional 30 minutes). Its Telemedicine and Direct Patient Contact Payment Policy carries a positive list — \"List of Eligible CPT/HCPCS for Two-way, Synchronous Telemedicine for Commercial Plans\" — and 99425 does not appear anywhere in that document. Absence from the list is not a documented denial, so this is recorded as unestablished rather than as not allowed, and it is a weaker signal than it looks: the policy carries \"Last Review: June, 2021\" and its revision log ends at 01/01/2022, while Aetna directs providers to the Availity provider portal for the current eligible-code list. Ask Aetna for the current list before billing this code via telehealth.","source":"Aetna — Telemedicine and Direct Patient Contact Payment Policy, retrieved 2026-08-12"}'::jsonb, 'unknown', 0.6, DATE '2022-01-01', NULL, 'f1000000-000f-4000-8000-00000000a00f'::uuid, 'Telemedicine and Direct Patient Contact Payment Policy — List of Eligible CPT/HCPCS for Two-way, Synchronous Telemedicine for Commercial Plans', 'extract:aetna-telemedicine-2026-08'),
  ('a09cf65c-6aec-4e42-8b81-35a0fa5f5c96'::uuid, 'a0000000-0000-4000-8000-000000000301'::uuid, 'OH', 'commercial', '99426', 'telehealth_allowed', '{"answer":"Aetna publishes no telemedicine eligibility for 99426 (principal care management, first 30 minutes of clinical staff time). Its Telemedicine and Direct Patient Contact Payment Policy carries a positive list — \"List of Eligible CPT/HCPCS for Two-way, Synchronous Telemedicine for Commercial Plans\" — and 99426 does not appear anywhere in that document. Absence from the list is not a documented denial, so this is recorded as unestablished rather than as not allowed, and it is a weaker signal than it looks: the policy carries \"Last Review: June, 2021\" and its revision log ends at 01/01/2022, while Aetna directs providers to the Availity provider portal for the current eligible-code list. Ask Aetna for the current list before billing this code via telehealth.","source":"Aetna — Telemedicine and Direct Patient Contact Payment Policy, retrieved 2026-08-12"}'::jsonb, 'unknown', 0.6, DATE '2022-01-01', NULL, 'f1000000-000f-4000-8000-00000000a00f'::uuid, 'Telemedicine and Direct Patient Contact Payment Policy — List of Eligible CPT/HCPCS for Two-way, Synchronous Telemedicine for Commercial Plans', 'extract:aetna-telemedicine-2026-08'),
